/**
 * What the Worker receives in `env`.
 *
 * `Cloudflare.Env` is generated by `wrangler types` from wrangler.jsonc, plus the names in a local
 * .dev.vars when there is one. The secrets are declared here instead, as optional on purpose: the
 * Worker is deployed before the secrets are set with `wrangler secret put`, and until then they are
 * undefined. `Omit` drops any copy `wrangler types` made from .dev.vars, which would say "always set".
 */
export type Env = Omit<Cloudflare.Env, "MCP_TOKEN" | "GITHUB_TOKEN"> & {
	/** The 48-hex-character token clients send to /mcp as `Authorization: Bearer <MCP_TOKEN>`. */
	MCP_TOKEN?: string;
	/** A fine-grained GitHub token for NOTES_REPO only, with Contents access. */
	GITHUB_TOKEN?: string;
};
